import{_ as s,a0 as a,w as p,s as i,ao as d,I as u,x as e,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux有问必答：如何在Ubuntu中升级Docker | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在Ubuntu中升级Docker | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在Ubuntu中升级Docker | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在Ubuntu中升级Docker | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150330 Linux FAQs with Answers--How to upgrade Docker on Ubuntu","title":"Linux有问必答：如何在Ubuntu中升级Docker","tag":"201505","desc":""},"relativePath":"201505/20150330 Linux FAQs with Answers--How to upgrade Docker on Ubuntu.md","filePath":"[post].md"}'),l={name:"201505/20150330 Linux FAQs with Answers--How to upgrade Docker on Ubuntu.md"};function k(m,t,D,c,b,x){const o=a("Link");return p(),i("div",null,[t[13]||(t[13]=d(`<h1 id="linux有问必答-如何在ubuntu中升级docker" tabindex="-1">Linux有问必答：如何在Ubuntu中升级Docker <a class="header-anchor" href="#linux有问必答-如何在ubuntu中升级docker" aria-label="Permalink to “Linux有问必答：如何在Ubuntu中升级Docker”">​</a></h1><blockquote><p><strong>提问</strong>: 我使用了Ubuntu的标准仓库安装了Docker。然而，默认安装的Docker不能满足我另外一个依赖Docker程序的版本需要。我该如何在Ubuntu中升级到Docker的最新版本？</p></blockquote><p>Docker第一次在2013年发布，它快速地演变成了一个针对分布式程序的开发平台。为了满足工业期望，Docker正在紧密地开发并持续地带来新特性的升级。这样Ubuntu发行版中的Docker版本可能很快就会过时。比如， Ubuntu 14.10 Utopic 中的Docker版本是1.2.0， 然而最新的Docker版本是1.6.0。</p><p><img src="https://farm9.staticflickr.com/8730/16351300024_9acb9086da_b.jpg" alt=""></p><p>对于那些想要跟随Docker的最新开发的人而言，Canonical为Docker维护了一个独立的PPA。使用这个PPA仓库，你可以很容易地在Ubuntu上升级到最新的Docker版本。</p><p>下面是如何设置Docker的PPA和升级Docker。</p><pre><code>$ sudo add-apt-repository ppa:docker-maint/testing
$ sudo apt-get update
$ sudo apt-get install docker.io
</code></pre><p>检查安装的Docker版本：</p><pre><code>$ docker --version
</code></pre><hr><pre><code>Docker version 1.5.0-dev, build a78ce5c
</code></pre><hr>`,12)),u("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"http://ask.xmodulo.com/upgrade-docker-ubuntu.html"},{default:n(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/upgrade-docker-ubuntu.html",-1)])]),_:1})]),u("p",null,[t[5]||(t[5]=e("作者：",-1)),r(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:n(()=>[...t[2]||(t[2]=[e("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:n(()=>[...t[3]||(t[3]=[e("geekpi",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),u("p",null,[t[10]||(t[10]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),r(o,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const L=s(l,[["render",k]]);export{T as __pageData,L as default};
